public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // Build adjacency list
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new java.util.ArrayList<>());
    }

    if (paths != null) {
        for (int[] path : paths) {
            if (path != null && path.length >= 2) {
                int u = path[0];
                int v = path[1];
                if (u >= 0 && u < n && v >= 0 && v < n) {
                    adj.get(u).add(v);
                    adj.get(v).add(u);
                }
            }
        }
    }

    int startNode = start[0];
    int endNode = end[0];

    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }

    // BFS
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    boolean[] visited = new boolean[n];
    queue.offer(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endNode) {
            return "can be travelled";
        }
        for (int neighbor : adj.get(current)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

