    int len2 = word2.length();
    int sumLen = len1 + len2;

    if (sumLen == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Count common letters (case-insensitive)
    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        if (Character.isLetter(c)) {
            count1[Character.toUpperCase(c) - 'A']++;
        }
    }

    for (char c : word2.toCharArray()) {
        if (Character.isLetter(c)) {
            count2[Character.toUpperCase(c) - 'A']++;
        }
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(count1[i], count2[i]);
    }

    // Reduce the fraction common/sumLen
    int numerator = common;
    int denominator = sumLen;

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Date string cannot be null or empty");
    }

    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Date must be in format 'MM dd yyyy'");
    }

    int month;
    int day;
    int year;

    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid date format: " + date);
    }

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Month must be between 1 and 12");
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Day must be between 1 and 31");
    }
    if (year < 1) {
        throw new IllegalArgumentException("Year must be positive");
    }

    java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
    java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy");
    String formattedDate = localDate.format(formatter);
    String weekday = localDate.getDayOfWeek().toString();

    return formattedDate + " is a " + weekday;
}

