public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    long total = (long) n * n;
    long target = total / n;
    long operations = 0;
    for (int i = 0; i < n; i++) {
        long val = 2L * i + 1;
        if (val < target) {
            operations += target - val;
        }
    }
    return (int) operations;
}

