        minSum = Math.min(minSum, currentMin);
    }

    return Math.max(Math.abs(maxSum), Math.abs(minSum));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    // Greedy approach: always pick the largest Fibonacci number <= remaining k
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (fibs.get(i) <= remaining) {
            remaining -= fibs.get(i);
            count++;
            if (remaining == 0) {
                break;
            }
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }

    return -1;
}

