public String getSmallestString(int n, int k) {
    if (n <= 0 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input: n must be positive and k must be between n and 26*n");
    }

    char[] result = new char[n];
    // Start with all 'a's
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // Remaining value to distribute
    int remaining = k - n;

    // Distribute the remaining value from right to left to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0; i--) {
        if (remaining <= 0) break;
        // How much can we add to this position? Max is 25 (from 'a' to 'z')
        int add = Math.min(remaining, 25);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

