        }
    }

    String result = sb.toString();
    if (negative) {
        result = "-" + result;
    }

    return result;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    // Sort to handle duplicates
    java.util.Arrays.sort(A);

    // Precompute which pairs sum to a perfect square
    boolean[][] isSquare = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int sqrt = (int) Math.sqrt(sum);
                isSquare[i][j] = (sqrt * sqrt == sum);
            }
        }
    }

    int[] count = {0};
    boolean[] used = new boolean[n];

    // Backtracking
    backtrack(0, n, A, isSquare, used, count);

    return count[0];
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int[] stack = new int[n];
    int top = -1;

    // Find the index of the previous smaller element for each bar
    for (int i = 0; i < n; i++) {
        while (top >= 0 && heights[stack[top]] >= heights[i]) {
            top--;
        }
        left[i] = (top == -1) ? -1 : stack[top];
        stack[++top] = i;
    }

    // Reset stack
    top = -1;

    // Find the index of the next smaller element for each bar
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && heights[stack[top]] >= heights[i]) {
            top--;
        }
        right[i] = (top == -1) ? n : stack[top];
        stack[++top] = i;
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        int area = heights[i] * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int total = rows * cols;
    int[] result = new int[total];

    int index = 0;
    // There are rows + cols - 1 diagonals
    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Even diagonal: go from bottom-left to top-right
            // Start row: max(0, d - cols + 1)
            // Start col: min(d, cols - 1)
            int startRow = Math.max(0, d - cols + 1);
            int startCol = Math.min(d, cols - 1);
            int r = startRow;
            int c = startCol;
            while (r >= 0 && c < cols) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Odd diagonal: go from top-right to bottom-left
            // Start row: min(d, rows - 1)
            // Start col: max(0, d - rows + 1)
            int startRow = Math.min(d, rows - 1);
            int startCol = Math.max(0, d - rows + 1);
            int r = startRow;
            int c = startCol;
            while (r < rows && c >= 0) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the rightmost digit that is smaller than the digit to its right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit exists, the number is the largest possible permutation
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit to the right of i that is greater than digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting from i+1 to get the smallest possible number
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert back to integer
    String resultStr = new String(digits);
    try {
        return Integer.parseInt(resultStr);
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    // Pairs that are center symmetric: (0,0), (1,1), (6,9), (8,8), (9,6)
    // For the outer pairs, we can use: (0,0), (1,1), (6,9), (8,8), (9,6)
    // But for the first digit, we cannot have 0 (unless n == 1)

    char[] pairs = {'0', '1', '6', '8', '9'};
    char[] reversePairs = {'0', '1', '9', '8', '6'};

    int half = n / 2;
    int mid = n % 2;

    // Generate all combinations for the first half
    List<String> firstHalf = new ArrayList<>();
    generateFirstHalf(firstHalf, half, pairs, 0);

    for (String prefix : firstHalf) {
        // Build the full number
        StringBuilder sb = new StringBuilder(prefix);

        if (mid == 1) {
            // Add middle character: 0, 1, or 8
            for (char midChar : new char[]{'0', '1', '8'}) {
                sb.append(midChar);
                // Add the reverse of the prefix
                for (int i = prefix.length() - 1; i >= 0; i--) {
                    char c = prefix.charAt(i);
                    sb.append(reversePairs[findIndex(pairs, c)]);
                }
                result.add(sb.toString());
                sb.setLength(prefix.length()); // reset to prefix length
            }
        } else {
            // No middle character
            for (int i = prefix.length() - 1; i >= 0; i--) {
                char c = prefix.charAt(i);
                sb.append(reversePairs[findIndex(pairs, c)]);
            }
            result.add(sb.toString());
        }
    }

    // Filter out numbers with leading zeros (unless n == 1)
    if (n > 1) {
        result.removeIf(s -> s.charAt(0) == '0');
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if all three points are distinct
    if (x1 == x2 && y1 == y2) return false;
    if (x1 == x3 && y1 == y3) return false;
    if (x2 == x3 && y2 == y3) return false;

    // Check if the three points are collinear using cross product
    // (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1) == 0 means collinear
    long cross = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] ugly = new int[n];
    ugly[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;

    for (int i = 1; i < n; i++) {
        int min = Math.min(next2, Math.min(next3, next5));
        ugly[i] = min;

        if (min == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (min == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (min == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }

    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            currentEnergy = 1;
        }
        if (currentEnergy > maxEnergy) {
            maxEnergy = currentEnergy;
        }
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

